const inside = { name: "env", variable: "INSIDE" };
const outside = { name: "env", variable: "OUTSIDE" };

export function mapAndFlood() {
  return {
    inside: Deno.permissions.querySync(inside).state,
    outside: Deno.permissions.querySync(outside).state,
    first: Deno.permissions.requestSync(inside).state,
    second: Deno.permissions.requestSync(inside).state,
  };
}
